import{_ as a,o as s,c as n,a2 as e}from"./chunks/framework.BnBoz4Zl.js";const g=JSON.parse('{"title":"第 12 章 从整理桌面文件这些小事做起","description":"本章只解决一个问题：文件越堆越多、找起来越来越慢。读完你会得到一套「单一入口 + AI 辅助整理」的资料管理方法，先花 30 分钟完成起步，之后每次用到哪个文件就顺手规范化哪个，一个月后常用文件自然变整齐。方法改编自公开文章《从翻半天到 3 秒找到，我的资料管理换了套法子》（AI干货日记…","frontmatter":{},"headers":[],"relativePath":"bluebook/第二篇 案例篇：从一项任务到一支 AI 团队/第 12 章 从整理桌面文件这些小事做起/index.md","filePath":"bluebook/第二篇 案例篇：从一项任务到一支 AI 团队/第 12 章 从整理桌面文件这些小事做起/index.md","lastUpdated":1786083382000}'),p={name:"bluebook/第二篇 案例篇：从一项任务到一支 AI 团队/第 12 章 从整理桌面文件这些小事做起/index.md"};function l(d,t,o,i,r,c){return s(),n("div",null,[...t[0]||(t[0]=[e(`<h1 id="第-12-章-从整理桌面文件这些小事做起" tabindex="-1">第 12 章 从整理桌面文件这些小事做起 <a class="header-anchor" href="#第-12-章-从整理桌面文件这些小事做起" aria-label="Permalink to &quot;第 12 章 从整理桌面文件这些小事做起&quot;">​</a></h1><p>本章只解决一个问题：文件越堆越多、找起来越来越慢。读完你会得到一套「单一入口 + AI 辅助整理」的资料管理方法，先花 30 分钟完成起步，之后每次用到哪个文件就顺手规范化哪个，一个月后常用文件自然变整齐。方法改编自公开文章《从翻半天到 3 秒找到，我的资料管理换了套法子》（AI干货日记，2026-08-06），出处见文末。</p><h2 id="_30-秒看懂-从「你整理」到「ai-替你整理」" tabindex="-1">30 秒看懂：从「你整理」到「AI 替你整理」 <a class="header-anchor" href="#_30-秒看懂-从「你整理」到「ai-替你整理」" aria-label="Permalink to &quot;30 秒看懂：从「你整理」到「AI 替你整理」&quot;">​</a></h2><p>传统做法是给文件分文件夹、起好名字、记住位置。文件超过一千个以后，这套方法就会失效：一个文件只能待在一个文件夹里，而你找它时记住的关键词是随机的；命名靠心情，三个月后自己都不认识；整理太累，于是总拖延。AI 改变的是分工——你只负责「把东西丢进同一个入口」，改名、分类、打标签、找文件都交给 AI。</p><table tabindex="0"><thead><tr><th>环节</th><th>以前（手动）</th><th>现在（AI 辅助）</th></tr></thead><tbody><tr><td>存文件</td><td>想半天放哪个文件夹</td><td>丢进一个入口就行</td></tr><tr><td>命名</td><td>「合同1」「最终版」</td><td>AI 批量改成规范名</td></tr><tr><td>分类</td><td>手动拖来拖去</td><td>AI 读内容自动打标签</td></tr><tr><td>找文件</td><td>靠记忆 + 关键词搜</td><td>一句话问，直接给答案</td></tr><tr><td>用的时候</td><td>打开翻正文</td><td>AI 直接摘要 + 定位段落</td></tr></tbody></table><p>对应上面的对照表，完整流程是五步：</p><ol><li><strong>收口</strong>：把散落各处的入口收成一个「主仓库」，最外层只建 4 个文件夹。</li><li><strong>集中</strong>：所有新文件先进收件箱，不做分类决策。</li><li><strong>改名</strong>：让 AI 按命名模板批量生成规范文件名，人工核对后执行。</li><li><strong>打标签</strong>：用标签和资料台账替代深层文件夹，任何角度都能命中。</li><li><strong>问答</strong>：从「翻文件」改成「问文件」，AI 摘要、跨文件检索、按旧文档起草。</li></ol><h2 id="开始前准备" tabindex="-1">开始前准备 <a class="header-anchor" href="#开始前准备" aria-label="Permalink to &quot;开始前准备&quot;">​</a></h2><p>动手前先定三件事，全部完成后才开始改文件。本章所有提示词均为可直接复制的任务模板，替换参数即可使用。</p><ul><li><strong>选定主仓库</strong>：三个方案按人群选一个，不要同时维护多个。 <ul><li>方案 A：公司正在用的网盘或云文档（腾讯文档、企业微信微盘等），上班族首选，不用额外付费，同事发来的文件天然在里面。</li><li>方案 B：个人网盘 + 本地同步文件夹，适合多设备使用。</li><li>方案 C：笔记类工具（Notion、印象笔记等），适合资料以图文为主的人。</li></ul></li><li><strong>建 4 个文件夹</strong>：在主仓库最外层只建四个，不要建第五个。</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>00_收件箱      —— 所有新东西先扔这</span></span>
<span class="line"><span>01_进行中      —— 这个月在用的</span></span>
<span class="line"><span>02_已归档      —— 做完的、留档的</span></span>
<span class="line"><span>03_素材库      —— 反复要用的模板/图片/资料</span></span></code></pre></div><ul><li><strong>备份与权限</strong>：改名前先确认文件有副本（网盘回收站或本地备份）；批量改名、移动、删除前，先让 AI 生成预览清单并人工确认，不直接覆盖原文件。</li></ul><h2 id="案例一-30-分钟起步——收口、集中、改-10-个文件名" tabindex="-1">案例一：30 分钟起步——收口、集中、改 10 个文件名 <a class="header-anchor" href="#案例一-30-分钟起步——收口、集中、改-10-个文件名" aria-label="Permalink to &quot;案例一：30 分钟起步——收口、集中、改 10 个文件名&quot;">​</a></h2><h3 id="输入样例-合成" tabindex="-1">输入样例（合成） <a class="header-anchor" href="#输入样例-合成" aria-label="Permalink to &quot;输入样例（合成）&quot;">​</a></h3><p>虚构人物「行政专员小林」的电脑桌面有 43 个散乱文件，包括 <code>新建 XLS 工作表.xlsx</code>（12 个）、<code>微信图片_2025xxxx.jpg</code>（9 张）、<code>扫描件0034.pdf</code>、<code>合同1.docx</code>、<code>最终版.docx</code> 等，微信和邮箱里还散落着一批。她的目标是让未来三秒能找到任何一份。</p><h3 id="只读检查-第-1-步-5-分钟" tabindex="-1">只读检查（第 1 步，5 分钟） <a class="header-anchor" href="#只读检查-第-1-步-5-分钟" aria-label="Permalink to &quot;只读检查（第 1 步，5 分钟）&quot;">​</a></h3><p>先只做检查，不做任何移动。把下面的问题交给 AI 助手（如 WorkBuddy）：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>请帮我盘点当前桌面（或指定文件夹）的文件现状，先不要移动、删除或重命名任何文件。</span></span>
<span class="line"><span>输出一份清单，包含：文件总数、按类型统计数量、疑似重复或同名文件、</span></span>
<span class="line"><span>命名明显不规范的例子（如「新建 XLS 工作表.xlsx」「最终版.docx」）。按数量从多到少排序。</span></span></code></pre></div><p><strong>预期结果</strong>：一份统计清单，能回答「有多少文件、乱在哪」。</p><h3 id="人工确认-第-2-步-10-分钟" tabindex="-1">人工确认（第 2 步，10 分钟） <a class="header-anchor" href="#人工确认-第-2-步-10-分钟" aria-label="Permalink to &quot;人工确认（第 2 步，10 分钟）&quot;">​</a></h3><p>确认后执行两个动作：</p><ol><li>建好 4 个文件夹（00_收件箱 / 01_进行中 / 02_已归档 / 03_素材库）。</li><li>把桌面上所有散落的文件一股脑拖进 <code>00_收件箱</code>，先不分类。</li></ol><p><strong>验收要点</strong>：桌面只剩 4 个文件夹和程序快捷方式；所有散落文件都能在 <code>00_收件箱</code> 里找到，数量与盘点清单一致。</p><h3 id="执行与核对-第-3-步-15-分钟" tabindex="-1">执行与核对（第 3 步，15 分钟） <a class="header-anchor" href="#执行与核对-第-3-步-15-分钟" aria-label="Permalink to &quot;执行与核对（第 3 步，15 分钟）&quot;">​</a></h3><p>从收件箱里挑 10 个最近要用的文件，按命名模板让 AI 生成对照表：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>下面是我的文件名列表。请按照「日期_类别_对象_关键词_版本」的格式重写每一个文件名。</span></span>
<span class="line"><span>规则：</span></span>
<span class="line"><span>1. 日期用 8 位数字，取文件内容或修改时间能确定的日期；无法确定的写「日期未知」；</span></span>
<span class="line"><span>2. 类别从【合同/报表/方案/纪要/素材/其他】中选；</span></span>
<span class="line"><span>3. 无法判断的内容标注「待确认」；</span></span>
<span class="line"><span>4. 不要编造事实，宁可标注待确认也不猜测。</span></span>
<span class="line"><span>输出成两列表格：原文件名 | 新文件名。</span></span>
<span class="line"><span>（粘贴文件名列表）</span></span></code></pre></div><p><strong>预期结果</strong>：一张两列对照表，例如：</p><table tabindex="0"><thead><tr><th>原文件名</th><th>新文件名</th></tr></thead><tbody><tr><td>合同1.docx</td><td>20250312_合同_鑫达供应商_年度采购_待确认.docx</td></tr><tr><td>最终版.docx</td><td>20250620_方案_项目周报_终版.docx</td></tr><tr><td>扫描件0034.pdf</td><td>日期未知_其他_扫描件0034_待确认.pdf</td></tr></tbody></table><p><strong>人工确认</strong>：核对对照表，改错的手动调整，确认后照着改名，改完丢进 <code>01_进行中</code>。</p><p><strong>验收要点</strong>：10 个文件全部改名成功且名字与确认过的对照表一致；有「待确认」标记的文件未被动过；原文件内容未改变（抽查打开 2 个）。</p><h2 id="案例二-存量文件批量改名与建档" tabindex="-1">案例二：存量文件批量改名与建档 <a class="header-anchor" href="#案例二-存量文件批量改名与建档" aria-label="Permalink to &quot;案例二：存量文件批量改名与建档&quot;">​</a></h2><p>起步之后是几千个历史文件的「欠账」。原则：<strong>先别管全部，从最近半年开始，改完就停</strong>。更早的文件等真要用时再顺手改——目标是「能找到」，不是「很整齐」。</p><p>分两种情况处理：</p><p><strong>情况一：文件名里已有信息，只是格式乱。</strong> 把文件名列表复制出来（全选 → 复制为路径 → 粘贴到文本文件），直接使用案例一的改名提示词，AI 几秒钟给出对照表，核对后执行。</p><p><strong>情况二：文件名毫无信息（如 <code>扫描件0034.pdf</code>、<code>微信图片_20250312.jpg</code>）。</strong> 名字里没有可用信息，只能看内容。让 AI 批量生成摘要：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>以下是一批文件的文件名和对应内容摘要，请为每一份生成一句话概括，</span></span>
<span class="line"><span>说明它大概是什么、可能属于哪个项目。输出三列表格：文件名 | 一句话概括 | 建议类别。</span></span>
<span class="line"><span>内容无法判断的，概括写「无法判断」，类别写「待确认」。</span></span></code></pre></div><p><strong>纠错闭环</strong>：如果 AI 把一份合同误判为「其他」类别，不要手改一个结果就结束——把这条错误加进规则（例如「含有金额、甲乙双方、盖章页的是合同」），重新生成整份对照表，再核对一遍。这样同一类错误不会重复出现。</p><p><strong>验收要点</strong>：对照表里每一行都有概括和类别；标注「待确认」的文件单独列出并保持原样；改名执行前有确认记录；执行后抽样 5 个文件确认内容可正常打开。</p><h2 id="案例三-用标签和资料台账替代深层文件夹" tabindex="-1">案例三：用标签和资料台账替代深层文件夹 <a class="header-anchor" href="#案例三-用标签和资料台账替代深层文件夹" aria-label="Permalink to &quot;案例三：用标签和资料台账替代深层文件夹&quot;">​</a></h2><p>文件夹的毛病是「一个文件只能待一处」；标签不一样，一个文件可以同时贴五个，从哪个角度想起都能命中。做法是建一张「资料台账」，让 AI 填列。</p><p>台账字段固定为六列：<strong>文件名 / 类别 / 项目 / 关键词 / 摘要 / 链接</strong>。</p><ul><li>用云文档的多维表格（腾讯文档智能表格等）：把文件链接贴进去，让 AI 生成其余列。</li><li>用笔记工具（Notion 等）：建数据库，属性加「多选标签」。</li><li>最土也最通用的办法：在主仓库里建一个 <code>_索引.md</code>，一行一个文件，字段四个——<strong>名字、在哪、讲了啥、什么时候可能用到</strong>。</li></ul><p>索引文件的生成提示词：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>下面是一批文件，请为每个文件输出一行索引，格式为「文件名 | 所在位置 | 一句话内容 | 什么时候可能用到」。</span></span>
<span class="line"><span>「什么时候可能用到」这一列按业务场景写，比如「做年度采购对比时」「写项目总结时」；</span></span>
<span class="line"><span>无法判断的写「待确认」。</span></span>
<span class="line"><span>（粘贴文件名与位置清单）</span></span></code></pre></div><p><strong>关键提醒：标签别贪多。</strong> 一开始最多定 10 个标签（例如：合同、报价、方案、纪要、素材、模板、政策、参考、待办、存档），用满一个月不够再加。标签体系一乱，就和文件夹一样废了。</p><p><strong>验收要点</strong>：台账或索引中每条记录四到六个字段齐全；任意按类别筛选、按关键词搜索都能在 10 秒内定位文件；标签总数不超过 10 个且没有同义标签（如「合同」和「契约」并存）。</p><h2 id="案例四-从翻文件到问文件" tabindex="-1">案例四：从翻文件到问文件 <a class="header-anchor" href="#案例四-从翻文件到问文件" aria-label="Permalink to &quot;案例四：从翻文件到问文件&quot;">​</a></h2><p>前三步把东西码好，这一步是「真正用起来」。找资料从「找到文件 → 打开 → 翻到那一页 → 复制那段话」变成「问一句，直接拿答案」。三个高频场景：</p><p><strong>场景一：一份长文档，只想知道结论。</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>这份文档一共讲了什么？用 5 句话总结。另外单独告诉我：</span></span>
<span class="line"><span>里面提到的关键金额、时间节点、责任人分别是什么，列成表格。</span></span></code></pre></div><p><strong>场景二：一堆文件，找哪份提到过某件事。</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>我记得去年有份材料里提到过供应商涨价的应对方案，是哪一份？帮我把相关段落摘出来，</span></span>
<span class="line"><span>注明出处文件名。</span></span></code></pre></div><p><strong>场景三：用旧资料改新东西。</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>这是我去年的项目总结（附上）。今年的情况变化是：团队从 5 人增加到 8 人、</span></span>
<span class="line"><span>预算减少 15%、新增了一条产品线。请基于旧文档的结构和语气，帮我起草今年的版本，</span></span>
<span class="line"><span>需要我补充具体数据的地方用【】标出来。</span></span></code></pre></div><p>这一步的前提是文件在同一个地方——这就是案例一「收口」为什么重要，环环相扣。</p><p><strong>安全提醒：AI 摘要不等于原文。</strong> 涉及合同金额、法律条款、财务数字、责任划分的内容，拿到摘要后必须点开原文核对关键段。做法是让 AI 摘要时始终带上出处，需要用时回原文扫一眼，多花二十秒，避免大错。</p><p><strong>验收要点</strong>：每个场景都拿到可复用的输出（总结 + 表格 / 出处段落 / 带【】的草稿）；所有金额、日期、责任人有原文出处可查；草稿中【】标记的数量与需要补充的数据点一致。</p><h2 id="替换参数" tabindex="-1">替换参数 <a class="header-anchor" href="#替换参数" aria-label="Permalink to &quot;替换参数&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>示例</th><th>换成你自己的</th></tr></thead><tbody><tr><td>主仓库</td><td>腾讯文档 / 个人网盘</td><td>你选定的唯一仓库</td></tr><tr><td>4 个文件夹名</td><td>00_收件箱 等</td><td>可保留，或改成你习惯的编号</td></tr><tr><td>命名模板</td><td>日期_类别_对象_关键词_版本</td><td>可增删字段，但日期必须在前</td></tr><tr><td>类别集合</td><td>合同/报表/方案/纪要/素材/其他</td><td>按你的工作内容调整</td></tr><tr><td>标签集合</td><td>合同、报价、方案……（≤10 个）</td><td>按业务场景自定义</td></tr><tr><td>台账字段</td><td>文件名/类别/项目/关键词/摘要/链接</td><td>可增删，但「关键词」和「链接」建议保留</td></tr><tr><td>起步文件数</td><td>10 个</td><td>最近要用的任意数量</td></tr></tbody></table><h2 id="常见弯路与人工确认点" tabindex="-1">常见弯路与人工确认点 <a class="header-anchor" href="#常见弯路与人工确认点" aria-label="Permalink to &quot;常见弯路与人工确认点&quot;">​</a></h2><p><strong>常见弯路</strong>（改编自原文「三个坑」，并补充本书视角）：</p><ol><li><strong>工具换来换去</strong>。这个月换笔记软件、下个月搬家，每次都是从头开始，资料反而更散。选定一个，用满三个月再评价——工具能力的差距，远小于「有没有认真用」的差距。</li><li><strong>把 AI 摘要当成原文</strong>。摘要会漏细节、可能理解偏。合同金额、法律条款、财务数字、责任划分必须回原文核对。</li><li><strong>只建系统，不定清理时间</strong>。再好的系统不清理也会烂掉。固定一个「每周十分钟」：把 <code>00_收件箱</code> 清空，该归档归档、该删删、该补标签补上。</li><li><strong>完美主义</strong>（原文观点）：想一次性收拾完五千个文件，结果一个都没改。目标是「能找到」而不是「很整齐」，从最近半年开始、用到哪个改哪个。</li><li><strong>文件夹越分越深</strong>（本书补充）：层级越深越不想放，越不想放越散。细分的活交给标签，不要建第五个文件夹。</li></ol><p><strong>人工确认点</strong>：</p><ul><li>批量改名、移动、删除执行前，必须看 AI 生成的预览清单并逐项确认。</li><li>出现「待确认」标记的文件，保持原样，不猜测、不补造。</li><li>涉及金额、条款、责任划分的内容，回原文核对后再使用。</li><li>主仓库的选择是个人决策，AI 只给方案 A/B/C，不替你定。</li></ul><p><strong>安全边界</strong>：不改源文件、不自动外发；所有写操作有预览、有确认、可回退；本文方法只是整理习惯，不构成任何公司正式制度或流程。</p><h2 id="来源与改编说明" tabindex="-1">来源与改编说明 <a class="header-anchor" href="#来源与改编说明" aria-label="Permalink to &quot;来源与改编说明&quot;">​</a></h2><ul><li>原文：<a href="https://mp.weixin.qq.com/s/W2O8QXKZmABYuF43FmaHoQ" target="_blank" rel="noreferrer">《从翻半天到 3 秒找到，我的资料管理换了套法子》</a>，公众号「AI干货日记」，2026-08-06 发布，访问日期 2026-08-06。</li><li>改编方式：文章是通用资料管理经验分享，本章将其重构为「单一入口 + AI 辅助」的四步任务链，并落到 WorkBuddy 提示词场景；文中人物（小林）、文件名、数字均为合成示例；原文观点（如「完美主义是资料管理的第一杀手」）已按释义引用并注明来源，不构成本书或任何公司的正式结论。</li></ul>`,67)])])}const u=a(p,[["render",l]]);export{g as __pageData,u as default};
